import functools
import inspect

def func(a: int, b: str):
    return a, b

def wrapper(f):
    @functools.wraps(f)
    def w(*args, **kwargs):
        return f(*args, **kwargs)
    return w

wrapped_func = wrapper(func)
print(f"Original signature: {inspect.signature(func)}")
print(f"Wrapped signature: {inspect.signature(wrapped_func)}")
